#!/usr/bin/env python3
"""Run all bench-pod simulations and write mechanical/sim/REPORT.md (+ plots/).

    python3 mechanical/sim/run_all.py            # all sizes in params.json
    python3 mechanical/sim/run_all.py --sizes OP-100

Reads mechanical/params.json (single parameter source of the CAD) and, if present, mechanical/out/bench/OP-xx.mech.json /
layout.json; assumptions for materials, friction and process tolerances are in common.CONST.  Bench test project only.
"""
from __future__ import annotations

import argparse
import hashlib
import pathlib
import re
import sys
import time

HERE = pathlib.Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))

import a1_drive, a2_dose, a3_tolerance, a4_structural, a5_fluidics, a6_seal  # noqa: E402
from common import CONST as C, MECH, Ctx, table  # noqa: E402


def natural(r):
    m = re.match(r"(\d+)\.(\d+)", r.id)
    return (int(m.group(1)), int(m.group(2)), r.id) if m else (99, 0, r.id)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--sizes", nargs="*")
    args = ap.parse_args()
    ctx = Ctx(args.sizes)
    t0 = time.time()
    # dependency order: A1 (thrust, seal) -> A4 (stiffness) -> A2 / A3 / A5
    r1 = a1_drive.run(ctx)
    r4 = a4_structural.run(ctx)
    r2 = a2_dose.run(ctx)
    r3 = a3_tolerance.run(ctx)
    r5 = a5_fluidics.run(ctx)
    r6 = a6_seal.run(ctx)
    results = [r1, r2, r3, r4, r5, r6]
    rows = sorted([r for res in results for r in res.rows], key=natural)
    cnt = {k: sum(1 for r in rows if r.status == k) for k in ("PASS", "WARN", "FAIL", "INFO")}

    p = (MECH / "params.json").read_bytes()
    sh = ctx.shared
    a1, a4, a3, a5, a2 = sh["a1"], sh["a4"], sh["a3"], sh["a5"], sh["a2"]
    zm, zs = ctx.active
    def _mi(s):
        m = ctx.mech[s]
        g = m.get("gears")
        return "%s: %.1f mm long, %s" % (s, m["length"], ("gears %d:%d" % (g["z_motor"], g["z_screw"])) if g else "coaxial (no gear pair)")
    mech_info = ", ".join(_mi(s) for s in ctx.sizes if s in ctx.mech) or "no mech.json found"

    occ = [v for v in a5["occ"].values() if v[0] > 0]
    v_lo, v_hi = min(v[1] for v in occ), max(v[1] for v in occ)
    t_lo, t_hi = min(v[4] for v in occ), max(v[4] for v in occ)
    out = []
    w = out.append
    w("# OpenPatch bench pod: simulation report (mechanics, drive, dosing, fluidics)\n")
    w("Bench test project only (WATER ONLY, never insulin or any drug), never on a person.  Generated by `python3 mechanical/sim/run_all.py` (%.0f s); "
      "inputs: `mechanical/params.json` (sha1 %s), `mechanical/out/bench/*.mech.json`.  Re-run after every CAD change.\n" % (time.time() - t0, hashlib.sha1(p).hexdigest()[:10]))
    w("**Model state:** gear pair in `params.json`: **%d:%d** (U/step %.5f, centre %.2f mm); sizes %s; CAD snapshots read: %s.  "
      "The OP-200 `mech.json` in `out/bench` still comes from an older coaxial snapshot (82.6 mm long), so OP-200 numbers use only its stroke from `params.json`.\n"
      % (zm, zs, ctx.u_per_step(zm, zs), ctx.centre(zm, zs), ", ".join(ctx.sizes), mech_info))

    w("## Summary\n")
    w("**%d PASS, %d WARN, %d FAIL**, %d info rows.\n" % (cnt["PASS"], cnt["WARN"], cnt["FAIL"], cnt["INFO"]))
    w("Read the status with its confidence: rows that rest on *geometry from the CAD* (tongue stress, lid/reservoir stack, thread and collar budget, 105 mA current limit, prime volume, snap-arm strain) "
      "are firm; rows that rest on *[ASM] friction or process inputs* (seal friction, once-per-rev screw error, stick-slip, compliance, bubble size) show what the design **needs** and which side of the line "
      "a plausible value lands on, and are settled only by the bench tests listed at the end.\n")
    CAD = {"1.1", "1.2", "1.10", "1.11", "2.1", "2.2", "3.1", "3.2", "3.3", "3.4", "3.5", "3.6", "3.7", "3.8", "4.1", "4.2", "4.3", "4.4", "4.5", "4.6", "4.7", "4.9", "4.10", "4.11", "5.1", "5.2", "5.3", "6.1"}
    basis = lambda r: "CAD" if (r.id in CAD or r.id.startswith("4.8")) else "model [ASM]"
    w(table(["ID", "Requirement", "Value", "Margin", "Status", "Basis", "Note"], [[r.id, r.requirement, r.value, r.margin, "**%s**" % r.status if r.status in ("FAIL", "WARN") else r.status, basis(r), r.note] for r in rows]))

    w("## Key findings (in order of consequence)\n")
    w("1. **Thrust is the main risk, not the leadscrew or the gears.**  With the controller's 105 mA phase limit the plunger thrust is only **%.1f N** (spec 4 assumes ~9.5 N, which neglects the current limit, "
      "the thrust-collar friction that is as large as the thread friction, and a 0.64 gearhead efficiency).  At the rated 181 mA it is %.1f N.  The silicone plunger seal (2 rings x 0.8 mm, 0.13 mm squeeze, "
      "37.7 mm perimeter) is modelled at **%.1f N kinetic / %.1f N breakaway** (plausible range 3-20 N); the drive can afford only about **%.1f N kinetic** at 105 mA.  Levers: current (R69), a ball/pin thrust end "
      "(%.1f N at 105 mA), a step-down gear pair 16:20 (%.1f N), and above all a seal with less squeeze/contact width.  The spec's 15:12 pair is the weakest of those evaluated.\n"
      % (a1["F_avail"], a1["F_avail_rated"], a1["F_seal"], a1["F_seal_break"], a1["budget"], a1["F_ball"], a1["F_step_down"]))
    w("2. **The carriage tongue (0.6 mm thick in the load direction) cannot carry the thrust**: root stress %.0f MPa per newton, %.0f MPa at 3 N vs ~45 MPa PA12 allowable (allowable thrust %.1f N) and a "
      "stiffness of only %.0f N/mm, which makes the plunger wind up %.2f U per 3 N.  It also dominates dose error and the stored volume at occlusion.\n"
      % (a4["sig_t_per_N"], 3 * a4["sig_t_per_N"], a4["F_allow_tongue"], a4["k_tongue"], 3 / a4["k_train"] * ctx.A / 10))
    w("3. **Stack-ups at the limit**: the CNC reservoir top (z 7.5) sits **%.2f mm** below the lid underside (z 7.6): P(contact) %.0f %% MJF / %.0f %% SLA; nominal height is exactly 8.5 so ~half of MJF pods exceed it; "
      "the gear centre equals the theoretical centre (zero backlash by design) while passive location of the printed bores plus a floating motor gives +-%.2f mm (backlash window only %.2f mm wide); "
      "no vertical float exists between rail, nut and screw (z misfit up to %.2f mm vs %.2f mm float, MJF).\n"
      % (a3["gap_nom"], 100 * a3["out35"]["MJF"]["p_int"], 100 * a3["out35"]["SLA"]["p_int"], a3["out31"]["MJF"]["wc"], a3["out31"]["window"][1] - a3["out31"]["window"][0],
         a3["out32"]["MJF"]["wc_z"], a3["fl_z"]))
    w("4. **Dose accuracy** (+-5 %% at >= 1 U): quantisation, bore tolerance (+0.05/-0: 0 ... +1.3 %%), thermal (PP area vs liquid expansion cancel) are fine; the 1 U result is set by (a) the once-per-revolution error of the "
      "real rod (3 um -> 5 %% by itself), (b) stick-slip wind-up (needs a stiff tongue and low seal friction) and (c) the backlash take-up after each draw (firmware has none: first dose after a draw loses %.0f-%.0f %%).\n"
      % (100 * a2["lost_u"][0], 100 * a2["lost_u"][2]))
    w("5. **Fluidics**: priming path %.1f U (REFILL.md: 0.5 U; firmware MAX_PRIME 0.524 U) plus a **%.1f U air layer** in front of the plunger; occlusion is detected only after a stall, so stored volume (compliance x P_stall) "
      "adds to the 2 U threshold - total undelivered at alarm is %.1f-%.1f U (stored %.1f-%.1f U) over the plausible friction/current cases and the alarm takes %.0f-%.0f h at 0.5 U/h (4 h is the floor of the 2 U criterion).\n" % (a5["V_path_U"], a5["V_dead_U"], v_lo + 2, v_hi + 2, v_lo, v_hi, t_lo, t_hi))
    w("6. **Snap arms**: PA12 MJF is marginal (%.2f %% vs 3 %%), SLA fails (%.2f %% vs 2 %% for tough resin, 1.2 %% for standard resin) unless the free arm length grows from %.1f to >= %.1f mm; pull-off force %.1f N.  "
      "Gears, shaft, leadscrew buckling (OP-70/100 >> 10x; OP-200 5x at K=2), reservoir wall and hard stops pass.\n"
      % (100 * a4["snap"]["PA12_MJF"][0], 100 * a4["snap"]["SLA_tough"][0], a4["arm_L"], a4["Lmin"]["SLA_tough"], 2 * a4["wedge"] * a4["snap"]["PA12_MJF"][1] / a4["trav"] * a4["overlap"]))

    for res in results:
        w(res.md)

    w("## Recommended design changes before ordering (for the CAD owner; not applied)\n")
    import math
    steps_takeup = math.ceil(a2['nut_play_max'] / (ctx.pitch / (ctx.spr * ctx.gh) * zm / zs))
    rec = [
        ("Thicken the carriage tongue (`seal.tongue_off`)", "from 0.6 to >= 1.2 mm in x (or add a gusset / steel pin): root stress drops 4x, allowable thrust %.1f -> 8 N, train stiffness %.0f -> %.0f N/mm.  Check the plunger socket (0.8 mm wide) and the reservoir slot follow." % (a4["F_allow_tongue"], a4["k_train"], a4["k_train_alt"]), "A4, A2, A5"),
        ("Recover thrust", "(a) raise the STSPIN220 current to ~150-180 mA (R69; VREF 0.105 V -> ~0.18 V) after a motor temperature check; (b) put a hardened pin / ball end (r_m <= 0.4 mm) against the thrust bush instead of the gear/bush face "
                           "(+%.0f %%); (c) prefer a step-down pair at the same centre such as **16:20** (centre 5.40, +25 %% torque, 0.00395 U/step) or 15:21 over 18:18 / 15:12; 15:12 gives the least thrust of all options and the parts list says it does not fit the lane anyway." % (100 * (a1["F_ball"] / a1["F_avail"] - 1)), "A1"),
        ("Cut seal friction by design", "2 rings x 0.8 mm at 0.13 mm squeeze is about 4x a syringe stopper.  Use ONE ring or contact width <= 0.4 mm, cast oversize 0.1-0.2 mm (squeeze <= 0.07 mm/side), Shore 30-40, and a medical silicone oil film; "
                                         "target kinetic friction <= %.1f N (budget at 105 mA), breakaway <= %.1f N.  Mould change only (`op_mould.py`, `seal.*`); the CNC reservoir stays frozen." % (a1["budget"], 1.5 * a1["budget"]), "A1, A2"),
        ("Close the 0.1 mm reservoir-lid gap", "lid underside z 7.6 vs reservoir top z 7.5: add a >= 0.3 mm local recess in the lid over the reservoir (lid wall stays >= 0.6) or lower the floor under the reservoir by 0.3 mm; the reservoir envelope is frozen, the shell is not.", "A3"),
        ("Height budget", "decide: nominal 8.4 mm so that WC (MJF) <= 8.6 and RSS <= 8.5, or accept 8.5 +0.2 for the bench.  Same for the PCB under the lid (0.2 mm nominal clearance to the 1.3 mm keep-out).", "A3"),
        ("Gear centre and motor location", "design centre = theoretical + %.2f mm; locate the motor against a datum/spring (no 0.1 mm floating saddle) or slot the saddle; with SLA and a datum P(backlash in window) = %.0f %% (passive MJF: %.0f %%).  Match the firmware feature to the pair (`drive-nfp-608-26-45-g18-18` vs `g15-12`: 25 %% dose error)." % (a3["out31"]["window"][2], 100 * a3["out31"]["SLA"]["p_ok_imp"], 100 * a3["out31"]["MJF"]["p_ok_pass"]), "A3"),
        ("Float the nut", "give the nut pocket >= 0.3 mm of radial float in the plane normal to the axis (or add 0.2 mm z-float between rail and carriage) so that bush/rail errors of up to 0.3 mm do not load the thread; today MJF has P(drag > 10 %%) = %.0f %%." % (100 * a3["out32"]["MJF"]["p_loss"]), "A3"),
        ("Snap arms", "lengthen the free arm to >= %.1f mm (SLA tough) or keep PA12 MJF only and accept 2.6 %% strain; alternatively move the hook notch toward the dome equator (smaller G) to cut the deflection.  Add a lead-in >= 0.4 mm on the guard tube / recess for the dock capture.  Re-run after the cannula is measured." % a4["Lmin"]["SLA_tough"], "A3, A4"),
        ("Dead layer and priming", "move the plunger front stop so the dead layer is <= 0.3 mm (now 1.0 mm = %.1f U of trapped air); prime with the outlet up; cut the 10 mm fill side-branch / valve pocket volume or raise MAX_PRIME for the bench (path %.1f U vs 0.524 U)." % (a5["V_dead_U"], a5["V_path_U"]), "A5"),
        ("Fluid module (done, spec 3c)", "no check valve; clamped sandwich with O-ring face seal, gasket, axially compressed underside septum and a UV-glued needle; `check.py` fluid-boundary check covers every interface (see `SEAL-AND-DEAD-VOLUME.md` 2b).", "A5"),
        ("Firmware (tell the firmware owner)", "(i) backlash take-up of >= %d steps after every draw; (ii) occlusion threshold = 2 U minus stored volume, or add a pressure/current criterion that triggers before the stall (stored volume %.1f-%.1f U otherwise); (iii) limit the draw rate by fill-needle gauge (suction <= 30 kPa: %s) instead of a fixed 1000 pps; (iv) de-energise the driver between pulses." % (steps_takeup, v_lo, v_hi, ", ".join("%s %.0f pps" % (g, v) for g, v in a1["mx_pps"].items())), "A1, A2, A5"),
        ("Leadscrew supply", "specify a ground or rolled rod with measured once-per-rev error <= 3 um, or accept >= 10 % at 1 U; add a thrust shoulder/collar at BOTH ends (reverse thrust appears to bear on the Ø2 magnet against a Ø1.7 bush face, 0.9 mm2 (check in CAD)).  OP-200 has only 5x buckling margin (K=2): keep the far bush.", "A2, A4"),
    ]
    w(table(["#", "change", "why / numbers", "analysis"], [[i + 1, f"**{a}**", b, c] for i, (a, b, c) in enumerate(rec)]))

    w("## Bench tests that remain necessary (simulation cannot settle these)\n")
    tests = [
        "**Plunger seal friction**: pull test of the real cast plunger in a real PP bore (or a bore coupon), kinetic and breakaway, dry / wet / oil-film, dwell 1 min / 1 h / 24 h, 3 squeeze levels.  This single number decides thrust margin, dose accuracy and occlusion behaviour (budget %.1f N kinetic)." % a1["budget"],
        "**Motor torque and heat**: thrust at the carriage with a force gauge vs phase current (105 / 150 / 181 mA) and step rate (50-1000 pps) on 5 motors; winding temperature after a 20 s draw and a 10 min hold; gearhead radial/axial load limit and backlash (ask the vendor for the drawing/curve).",
        "**Screw and nut**: no-load drag torque, collar friction with bush face vs pin end, nut axial play, once-per-rev axial error and lead error with a dial gauge/laser on real rods (target <= 3 um), 15 mm lead error.",
        "**Gear mesh**: backlash vs centre distance on MJF and SLA housings (feeler gauge / angular play), drag torque, noise; the position tolerance of printed bores on the real printer batch.",
        "**Carriage tongue / thrust train**: load-deflection to 8 N and failure test of 5 printed coupons (MJF PA12 and SLA), creep at 4 N for 24 h; stiffness decides stick-slip.",
        "**Compliance and occlusion**: blocked outlet with a pressure sensor, record pressure vs steps (compliance mm3/kPa with and without a deliberate bubble), P_stall, alarm time at 0.5 U/h and 1.5 U/min, and the volume released when the block is removed.",
        "**Gravimetric dose accuracy** (balance 0.1 mg, water into a container): 0.05, 1, 10 U x 10 repeats at 5 / 20 / 40 C, before and after per-pod calibration, and the first dose after a draw.",
        "**Assisted pressure fill** (spec 3c): syringe pressure vs plunger retraction rate, pressure at the septum, surplus at the needle, bubble formation at the plunger face (outlet up); hold 30 kPa positive / 40 kPa vacuum at septum, O-ring, gasket and needle bond; self-locking test (50 kPa, motor unpowered); priming volume (<= 0.3 U).",
        "**Dock** (after the coupon measurement of the Insight Flex): insertion / pull-off force over 50 cycles, strain whitening or creep of the arms, needle lands in the septum for all coupon variants, capture with the lead-in.",
        "**Fit and closure**: measure heights, bore positions and thickness of the first MJF and SLA batch; check lid vs reservoir contact, gasket compression, PCB and component clearance.",
        "**Material data**: tensile/flexural data of the actual resin and PA12 lot (E, strain allowable) to replace the [ASM] values in `common.CONST`.",
    ]
    for i, t in enumerate(tests, 1):
        w(f"{i}. {t}")
    w("")
    w("## Method, assumptions and limits\n")
    w("* Every number that is not in `params.json` / the CAD json is a named constant in `mechanical/sim/common.py` with a tag: **[DS]** vendor page, **[LIT]** textbook / literature order of magnitude, **[ASM]** assumption to be replaced by a measurement.  Change a value there and re-run.\n"
      "* The models are first-order (power-screw formula, Euler beams, Lewis, Hagen-Poiseuille, clamped-strip plate, Gent E(Shore A) squeeze model, uniform/triangular Monte Carlo).  They bound the design, they do not replace tests; "
      "no FEA solver (CalculiX/gmsh) was used: all load paths are slender beams where closed-form results are adequate.\n"
      "* Printed-part allowables are for PA12 MJF and generic SLA resins; no insulin, biocompatibility, sterility or on-body aspect is analysed.\n"
      "* Thermal/battery analysis is out of scope (a one-line winding dissipation check is in 1.7).\n")
    w("Files: `common.py` (inputs), `a1_drive.py`, `a2_dose.py`, `a3_tolerance.py`, `a4_structural.py`, `a5_fluidics.py`, `run_all.py`, `plots/`.\n")
    (HERE / "REPORT.md").write_text("\n".join(out))
    print("REPORT.md written: %d PASS, %d WARN, %d FAIL, %d INFO (%.0f s)" % (cnt["PASS"], cnt["WARN"], cnt["FAIL"], cnt["INFO"], time.time() - t0))


if __name__ == "__main__":
    main()
